#pragma once

// Combine local first-preference polls with the seat support generated by the
// wider forecast. SimulationPreparation prepares one fixed target and weight
// per seat/party; SimulationIteration applies them to each possible election
// before the usual normalization and statewide FP reconciliation. This changes
// local support without changing the party's statewide polling projection.

#include "General.h"

#include <map>
#include <utility>
#include <vector>

namespace SeatFpPolls {

using Readings = std::vector<std::pair<float, int>>;
enum class ReadingTreatment { Reported, Independent };

struct PreparedPoll {
	// The poll average on the same log-odds scale as the generated seat share:
	// 25 * log(p / (100-p)), where p is a percentage of formal FP votes. Mixing
	// on this scale keeps the resulting percentage between zero and 100.
	double transformedTarget = 0.0;
	// Fraction of each generated share replaced by the fixed poll target (0--1).
	double contribution = 0.0;
};

using ByParty = std::map<int, PreparedPoll>;

// Readings contain (FP percentage, credibility rating), not sample sizes.
// A lower non-negative rating means stronger evidence. Keep the inherited
// independent weighting for all supported parties: each reading contributes
// 0.6^rating, and accumulating readings increases their combined influence
// towards a maximum of 80%. These are existing modelling choices, not newly
// fitted estimates for named minor parties. Dates, sample sizes and shared
// pollster errors are not separately modelled by this calculation.
//
// Only these fixed poll quantities are prepared once. The generated share,
// including national/regional movement and local uncertainty, is still supplied
// afresh for every iteration. No simulated outcome is cached here.
inline PreparedPoll prepare(
	Readings const& readings, ReadingTreatment treatment)
{
	double weightedSum = 0.0;
	double sumOfWeights = 0.0;
	for (auto const& [percentage, credibility] : readings) {
		constexpr double QualityWeightBase = 0.6;
		double const weight = myPow(QualityWeightBase, credibility);
		if (!std::isfinite(weight) || weight <= 0.0) continue;

		// Keep the existing empirical reading adjustment only for the IND
		// treatment. Its 0.503*p + 15.59 relationship describes historical
		// independent/pseudo-independent polls; it is not evidence about Greens
		// or One Nation readings. Named parties therefore use the reported
		// percentage directly (a 13% Greens reading stays 13%, not 22.13%).
		double pollPercentage = percentage;
		if (treatment == ReadingTreatment::Independent) {
			pollPercentage = percentage * 0.503 + 15.59;
		}
		weightedSum += pollPercentage * weight;
		sumOfWeights += weight;
	}
	if (sumOfWeights <= 0.0) return {};

	// A genuine 0% or 100% reading is valid input, but its log-odds value
	// would be infinite. The inherited 0.1--99.9% bounds keep the target finite;
	// they are a numerical safeguard, not a minimum candidate vote share.
	double const transformedPollFp = transformVoteShare(
		std::clamp<double>(weightedSum / sumOfWeights, 0.1, 99.9));
	constexpr double MaxPollWeight = 0.8;
	constexpr double PollWeightBase = 0.6;
	double const pollFactor = MaxPollWeight *
		(1.0 - std::pow(PollWeightBase, sumOfWeights));
	return {transformedPollFp, pollFactor};
}

// Apply evidence for this party only to one generated seat FP share, already
// on the transformed scale. Candidate presence and independent eligibility are
// decided by the caller's ordinary seat-generation path: this lookup must not
// create a candidate or transfer one party's poll to another candidate.
//
// Skip polls while calibrating this candidate's betting odds, as in the existing
// independent treatment. The calibrated odds and polls are combined afterwards
// in the main forecast. A missing poll leaves the share exactly unchanged.
// Each poll update is applied once, not repeatedly during FP reconciliation.
//
// Blending towards a fixed poll target changes both centre and uncertainty:
// differences between generated shares shrink by (1-contribution) on this scale.
// For one credibility-1 reading the contribution is about 21.1%. No additional
// random poll error is drawn; this preserves the independent method's behaviour.
inline double apply(
	ByParty const& polls, int partyIndex, double transformedVoteShare,
	bool calibratingCandidateOdds)
{
	if (calibratingCandidateOdds) return transformedVoteShare;
	auto const poll = polls.find(partyIndex);
	if (poll == polls.end() || poll->second.contribution <= 0.0) {
		return transformedVoteShare;
	}
	return mix(transformedVoteShare, poll->second.transformedTarget,
		poll->second.contribution);
}

} // namespace SeatFpPolls
